//! Exact parity between [`MisakiG2p`] and upstream misaki 0.9.4
//! `en.G2P(trf=False, fallback=None)` on the narration corpus, US and GB.
//!
//! The fixture (`tests/fixtures/misaki_g2p_oracle.json`) is checked in and
//! was generated by
//! `crates/boostr-audio/tests/tools/kokoro_g2p_oracle/kokoro_g2p_oracle.py`.
//! It holds the spaCy `en_core_web_sm` tokens misaki builds for each
//! sentence, so this test needs neither Python nor spaCy.
//!
//! Every sentence is checked against three outputs: the phoneme string with
//! misaki's default `unk`, the string with Kokoro's empty `unk`, and the
//! final tokens (text, whitespace, phonemes, rating). All mismatches print
//! before the test fails.
//!
//! `matches_misaki_on_narration_corpus` feeds the fixture's tokens.
//! `raw_text_through_spacy_tokenizer_matches_misaki` tokenizes the raw
//! sentence with [`SpacyTokenizer`] and takes only the tags from the
//! fixture. `raw_text_through_full_pipeline_matches_misaki` passes the raw
//! sentence to [`MisakiG2p::phonemize_text`]: tokenizer, tagger and G2P.

use boostr_audio::g2p::misaki::{G2pOutput, KOKORO_UNK, MToken, MisakiG2p};
use boostr_audio::g2p::spacy_tokenizer::SpacyTokenizer;
use serde::Deserialize;

mod common;
use common::load_json;

/// `[text, whitespace, phonemes, rating]` of one final token.
type TokenRow = (String, String, Option<String>, Option<u8>);

#[derive(Debug, Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    sentence: String,
    /// `[text, tag, whitespace]`.
    tokens: Vec<(String, String, String)>,
    us: Expected,
    gb: Expected,
}

#[derive(Debug, Deserialize)]
struct Expected {
    phonemes: String,
    phonemes_kokoro: String,
    token_phonemes: Vec<TokenRow>,
}

fn input(case: &Case) -> Vec<MToken> {
    case.tokens
        .iter()
        .map(|(text, tag, ws)| MToken::new(text.as_str(), tag.as_str(), ws.as_str()))
        .collect()
}

/// misaki `G2P.preprocess` on a sentence without markdown links:
/// `str.lstrip`.
fn preprocess(sentence: &str) -> &str {
    sentence.trim_start_matches(|c: char| c.is_whitespace() || ('\u{1c}'..='\u{1f}').contains(&c))
}

/// The sentence tokenized by [`SpacyTokenizer`], tagged with the fixture's
/// tags. `Err` reports a token text or whitespace that differs from the
/// fixture.
fn spacy_input(tokenizer: &SpacyTokenizer, case: &Case) -> Result<Vec<MToken>, String> {
    let tokens = tokenizer.tokenize(preprocess(&case.sentence));
    let got: Vec<(&str, &str)> = tokens
        .iter()
        .map(|t| (t.text.as_str(), t.whitespace()))
        .collect();
    let want: Vec<(&str, &str)> = case
        .tokens
        .iter()
        .map(|(text, _, ws)| (text.as_str(), ws.as_str()))
        .collect();
    if got != want {
        return Err(format!(
            "[spacy] {:?}\n  rust:  {got:?}\n  spacy: {want:?}",
            case.sentence
        ));
    }
    Ok(tokens
        .iter()
        .zip(&case.tokens)
        .map(|(t, (_, tag, _))| MToken::new(t.text.as_str(), tag.as_str(), t.whitespace()))
        .collect())
}

fn token_rows(out: &G2pOutput) -> Vec<TokenRow> {
    out.tokens
        .iter()
        .map(|t| {
            (
                t.text.clone(),
                t.whitespace.clone(),
                t.phonemes.clone(),
                t.rating,
            )
        })
        .collect()
}

/// Runs one dialect over every case with its input tokens; returns the
/// mismatch reports.
fn check_dialect(name: &str, british: bool, cases: &[(&Case, Vec<MToken>)]) -> Vec<String> {
    let g2p = MisakiG2p::new(british).unwrap_or_else(|e| panic!("MisakiG2p::new({british}): {e}"));
    let kokoro = MisakiG2p::new(british)
        .unwrap_or_else(|e| panic!("MisakiG2p::new({british}): {e}"))
        .with_unk(KOKORO_UNK);

    let mut failures = Vec::new();
    let mut exact = 0usize;
    for (case, tokens) in cases {
        let got = g2p.phonemize(tokens.clone());
        let got_kokoro = kokoro.phonemize(tokens.clone()).phonemes;
        match compare(name, british, case, &got, &got_kokoro) {
            None => exact += 1,
            Some(report) => failures.push(report),
        }
    }
    println!("{name}: {exact}/{} sentences exact", cases.len());
    failures
}

/// Runs one dialect over every raw sentence through
/// [`MisakiG2p::phonemize_text`]; returns the mismatch reports.
fn check_dialect_text(name: &str, british: bool, cases: &[Case]) -> Vec<String> {
    let g2p = MisakiG2p::new(british).unwrap_or_else(|e| panic!("MisakiG2p::new({british}): {e}"));
    let kokoro = MisakiG2p::new(british)
        .unwrap_or_else(|e| panic!("MisakiG2p::new({british}): {e}"))
        .with_unk(KOKORO_UNK);

    let mut failures = Vec::new();
    let mut exact = 0usize;
    for case in cases {
        let run = |g: &MisakiG2p| {
            g.phonemize_text(&case.sentence)
                .unwrap_or_else(|e| panic!("phonemize_text({:?}): {e}", case.sentence))
        };
        let got = run(&g2p);
        let got_kokoro = run(&kokoro).phonemes;
        match compare(name, british, case, &got, &got_kokoro) {
            None => exact += 1,
            Some(report) => failures.push(report),
        }
    }
    println!("{name} (raw text): {exact}/{} sentences exact", cases.len());
    failures
}

/// A mismatch report for one sentence, or `None` when all three outputs
/// match the fixture.
fn compare(
    name: &str,
    british: bool,
    case: &Case,
    got: &G2pOutput,
    got_kokoro: &str,
) -> Option<String> {
    let want = if british { &case.gb } else { &case.us };
    let got_rows = token_rows(got);
    let mut report = Vec::new();
    if got.phonemes != want.phonemes {
        report.push(format!(
            "  phonemes\n    rust:   {}\n    misaki: {}",
            got.phonemes, want.phonemes
        ));
    }
    if got_kokoro != want.phonemes_kokoro {
        report.push(format!(
            "  phonemes (unk='')\n    rust:   {}\n    misaki: {}",
            got_kokoro, want.phonemes_kokoro
        ));
    }
    if got_rows != want.token_phonemes {
        report.push(format!(
            "  tokens\n    rust:   {:?}\n    misaki: {:?}",
            got_rows, want.token_phonemes
        ));
    }
    if report.is_empty() {
        return None;
    }
    Some(format!(
        "[{name}] {:?}\n{}",
        case.sentence,
        report.join("\n")
    ))
}

#[test]
fn matches_misaki_on_narration_corpus() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/misaki_g2p_oracle.json"
    );
    let fixture: Fixture = load_json(std::path::Path::new(path));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");

    let cases: Vec<(&Case, Vec<MToken>)> = fixture.cases.iter().map(|c| (c, input(c))).collect();
    let mut failures = check_dialect("us", false, &cases);
    failures.extend(check_dialect("gb", true, &cases));
    for f in &failures {
        println!("{f}");
    }
    assert!(
        failures.is_empty(),
        "{} of {} sentence checks mismatched; see the output above",
        failures.len(),
        fixture.cases.len() * 2
    );
}

#[test]
fn raw_text_through_spacy_tokenizer_matches_misaki() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/misaki_g2p_oracle.json"
    );
    let fixture: Fixture = load_json(std::path::Path::new(path));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");
    let tokenizer =
        SpacyTokenizer::en_core_web_sm().unwrap_or_else(|e| panic!("SpacyTokenizer: {e}"));

    let mut failures = Vec::new();
    let mut cases = Vec::new();
    for case in &fixture.cases {
        match spacy_input(&tokenizer, case) {
            Ok(tokens) => cases.push((case, tokens)),
            Err(report) => failures.push(report),
        }
    }
    println!(
        "spacy: {}/{} sentences tokenized exactly",
        cases.len(),
        fixture.cases.len()
    );
    failures.extend(check_dialect("us", false, &cases));
    failures.extend(check_dialect("gb", true, &cases));
    for f in &failures {
        println!("{f}");
    }
    assert!(
        failures.is_empty(),
        "{} of {} tokenization and sentence checks mismatched; see the output above",
        failures.len(),
        fixture.cases.len() * 3
    );
}

#[test]
fn raw_text_through_full_pipeline_matches_misaki() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/misaki_g2p_oracle.json"
    );
    let fixture: Fixture = load_json(std::path::Path::new(path));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");

    let mut failures = check_dialect_text("us", false, &fixture.cases);
    failures.extend(check_dialect_text("gb", true, &fixture.cases));
    for f in &failures {
        println!("{f}");
    }
    assert!(
        failures.is_empty(),
        "{} of {} sentence checks mismatched; see the output above",
        failures.len(),
        fixture.cases.len() * 2
    );
}
